/*
    TeacherProfiles Department Promotion Script
    Generated from local dev database ANILMSI.EduSphere on 2026-09-13 04:50:53 +05:30.

    Scope:
      1. Adds dbo.TeacherProfiles.DepartmentId if it does not already exist.
      2. Adds IX_TeacherProfiles_DepartmentId if missing.
      3. Adds FK_TeacherProfiles_Departments_DepartmentId if missing.
      4. Updates DepartmentId for existing TeacherProfiles by Id.
      5. Inserts TeacherProfiles rows that are missing by Id.

    Dependency note:
      Missing inserts require matching Tenants, Branches, Departments, and nullable Users to already exist.
      Run the related tenant/branch/department/user seed scripts first if this script throws a dependency error.
*/

IF COL_LENGTH(N'dbo.TeacherProfiles', N'DepartmentId') IS NULL
BEGIN
    ALTER TABLE [dbo].[TeacherProfiles]
        ADD [DepartmentId] uniqueidentifier NULL;
END;
GO

SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    IF OBJECT_ID(N'tempdb..#TeacherProfilesSource') IS NOT NULL
        DROP TABLE #TeacherProfilesSource;

    CREATE TABLE #TeacherProfilesSource
    (
        [Id] uniqueidentifier NOT NULL PRIMARY KEY,
        [TenantId] uniqueidentifier NOT NULL,
        [UserId] uniqueidentifier NULL,
        [BranchId] uniqueidentifier NOT NULL,
        [DepartmentId] uniqueidentifier NULL,
        [EmployeeNumber] nvarchar(50) NOT NULL,
        [FirstName] nvarchar(100) NOT NULL,
        [MiddleName] nvarchar(100) NULL,
        [LastName] nvarchar(100) NOT NULL,
        [DateOfBirth] date NULL,
        [Gender] int NOT NULL,
        [Email] nvarchar(150) NULL,
        [PhoneNumber] nvarchar(30) NULL,
        [Designation] nvarchar(120) NULL,
        [Qualifications] nvarchar(500) NULL,
        [Specializations] nvarchar(500) NULL,
        [ExperienceYears] decimal(18,2) NOT NULL,
        [JoiningDate] date NOT NULL,
        [Status] int NOT NULL,
        [CreatedBy] nvarchar(128) NULL,
        [CreatedOn] datetime2 NOT NULL,
        [ModifiedBy] nvarchar(128) NULL,
        [ModifiedOn] datetime2 NULL,
        [IsDeleted] bit NOT NULL,
        [DeletedBy] nvarchar(max) NULL,
        [DeletedOn] datetime2 NULL,
        [ConcurrencyToken] uniqueidentifier NOT NULL
    );


    IF EXISTS (
        SELECT 1
        FROM #TeacherProfilesSource src
        WHERE NOT EXISTS (SELECT 1 FROM dbo.Tenants t WHERE t.Id = src.TenantId)
    )
        THROW 51000, 'TeacherProfiles promotion blocked: one or more source TenantId values do not exist in dbo.Tenants.', 1;

    IF EXISTS (
        SELECT 1
        FROM #TeacherProfilesSource src
        WHERE NOT EXISTS (SELECT 1 FROM dbo.Branches b WHERE b.Id = src.BranchId)
    )
        THROW 51001, 'TeacherProfiles promotion blocked: one or more source BranchId values do not exist in dbo.Branches.', 1;

    IF EXISTS (
        SELECT 1
        FROM #TeacherProfilesSource src
        WHERE src.DepartmentId IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM dbo.Departments d WHERE d.Id = src.DepartmentId)
    )
        THROW 51002, 'TeacherProfiles promotion blocked: one or more source DepartmentId values do not exist in dbo.Departments.', 1;

    IF EXISTS (
        SELECT 1
        FROM #TeacherProfilesSource src
        WHERE src.UserId IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM dbo.AspNetUsers u WHERE u.Id = src.UserId)
    )
        THROW 51003, 'TeacherProfiles promotion blocked: one or more source UserId values do not exist in dbo.AspNetUsers.', 1;

    IF EXISTS (
        SELECT 1
        FROM #TeacherProfilesSource src
        WHERE NOT EXISTS (SELECT 1 FROM dbo.TeacherProfiles tp WHERE tp.Id = src.Id)
          AND EXISTS (
              SELECT 1
              FROM dbo.TeacherProfiles tp
              WHERE tp.TenantId = src.TenantId
                AND tp.EmployeeNumber = src.EmployeeNumber
          )
    )
        THROW 51004, 'TeacherProfiles promotion blocked: a teacher profile with the same TenantId and EmployeeNumber exists under a different Id.', 1;

    UPDATE target
       SET target.DepartmentId = src.DepartmentId
    FROM dbo.TeacherProfiles AS target
    INNER JOIN #TeacherProfilesSource AS src ON src.Id = target.Id
    WHERE ISNULL(CONVERT(nvarchar(36), target.DepartmentId), N'') <> ISNULL(CONVERT(nvarchar(36), src.DepartmentId), N'');

    SELECT src.[Id], src.[TenantId], src.[UserId], src.[BranchId], src.[DepartmentId], src.[EmployeeNumber], src.[FirstName], src.[MiddleName], src.[LastName], src.[DateOfBirth], src.[Gender], src.[Email], src.[PhoneNumber], src.[Designation], src.[Qualifications], src.[Specializations], src.[ExperienceYears], src.[JoiningDate], src.[Status], src.[CreatedBy], src.[CreatedOn], src.[ModifiedBy], src.[ModifiedOn], src.[IsDeleted], src.[DeletedBy], src.[DeletedOn], src.[ConcurrencyToken]
    FROM #TeacherProfilesSource AS src
    WHERE NOT EXISTS (SELECT 1 FROM dbo.TeacherProfiles target WHERE target.Id = src.Id);

    IF NOT EXISTS (
        SELECT 1
        FROM sys.indexes
        WHERE name = N'IX_TeacherProfiles_DepartmentId'
          AND object_id = OBJECT_ID(N'dbo.TeacherProfiles')
    )
    BEGIN
        CREATE INDEX [IX_TeacherProfiles_DepartmentId]
            ON [dbo].[TeacherProfiles] ([DepartmentId]);
    END;

    IF EXISTS (
        SELECT 1
        FROM dbo.TeacherProfiles tp
        WHERE tp.DepartmentId IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM dbo.Departments d WHERE d.Id = tp.DepartmentId)
    )
        THROW 51005, 'TeacherProfiles promotion blocked: dbo.TeacherProfiles contains DepartmentId values that do not exist in dbo.Departments.', 1;

    IF NOT EXISTS (
        SELECT 1
        FROM sys.foreign_keys
        WHERE name = N'FK_TeacherProfiles_Departments_DepartmentId'
          AND parent_object_id = OBJECT_ID(N'dbo.TeacherProfiles')
    )
    BEGIN
        ALTER TABLE [dbo].[TeacherProfiles] WITH CHECK
            ADD CONSTRAINT [FK_TeacherProfiles_Departments_DepartmentId]
            FOREIGN KEY ([DepartmentId]) REFERENCES [dbo].[Departments] ([Id])
            ON DELETE NO ACTION;

        ALTER TABLE [dbo].[TeacherProfiles]
            CHECK CONSTRAINT [FK_TeacherProfiles_Departments_DepartmentId];
    END;

    SELECT
        COUNT_BIG(*) AS TeacherProfilesInSource,
        SUM(CASE WHEN src.DepartmentId IS NOT NULL THEN 1 ELSE 0 END) AS SourceRowsWithDepartment
    FROM #TeacherProfilesSource AS src;

    SELECT
        COUNT_BIG(*) AS TeacherProfilesInTarget,
        SUM(CASE WHEN DepartmentId IS NOT NULL THEN 1 ELSE 0 END) AS TargetRowsWithDepartment
    FROM dbo.TeacherProfiles;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;
    THROW;
END CATCH;
